import { RunResumeSessionManager } from "../runtime/resume-session.js";
import { AGENT_TIMEOUT } from "../../errors/index.js";
import { sleep } from "../../utils/index.js";
const DEFAULT_DETACHED_RUN_DRAIN_TIMEOUT_MS = 15_000;
const DETACHED_RUN_DRAIN_TIMEOUT_MESSAGE = "Detached durable runs did not drain before shutdown timeout";
/** Create detached run tracker. */
export function createDetachedRunTracker(options = {}) {
    const sessionManager = options.sessionManager ?? new RunResumeSessionManager();
    const activeRunIds = new Set();
    const settledRunIds = new Set();
    // Every outstanding execution per run id: a park-cancelled execution can
    // outlive the resumed execution that reused its run id.
    const activeExecutions = new Map();
    const defaultPollIntervalMs = options.pollIntervalMs ?? 50;
    const collectPendingRunIds = () => [
        ...new Set([...activeRunIds, ...activeExecutions.keys()]),
    ];
    const untrackRun = (runId) => {
        activeRunIds.delete(runId);
    };
    return {
        sessionManager,
        trackRun(runId) {
            activeRunIds.add(runId);
        },
        untrackRun,
        cancelRun(runId) {
            const cancelled = sessionManager.cancelRun(runId);
            if (cancelled) {
                untrackRun(runId);
            }
            return cancelled;
        },
        hasPendingExecution(runId) {
            return activeExecutions.has(runId);
        },
        hasSettledExecution(runId) {
            return settledRunIds.has(runId) && !activeExecutions.has(runId) && !activeRunIds.has(runId);
        },
        registerExecution(runId, execution) {
            settledRunIds.delete(runId);
            activeRunIds.add(runId);
            const trackedExecution = execution.finally(() => {
                const executions = activeExecutions.get(runId);
                if (!executions?.delete(trackedExecution) || executions.size > 0) {
                    return;
                }
                settledRunIds.add(runId);
                if (settledRunIds.size > 10_000)
                    settledRunIds.delete(settledRunIds.values().next().value);
                activeExecutions.delete(runId);
                untrackRun(runId);
            });
            // Only waitForDrain (shutdown) reads this promise. Without a rejection handler, a failure triggers an unhandled rejection and crashes the process.
            trackedExecution.catch(() => { });
            const executions = activeExecutions.get(runId) ?? new Set();
            executions.add(trackedExecution);
            activeExecutions.set(runId, executions);
        },
        cancelAllRuns() {
            const runIds = [...activeRunIds];
            for (const runId of runIds) {
                this.cancelRun(runId);
            }
            return runIds;
        },
        async waitForDrain(input) {
            const pollIntervalMs = input.pollIntervalMs ?? defaultPollIntervalMs;
            const deadline = Date.now() + input.timeoutMs;
            while (Date.now() <= deadline) {
                const pendingRunIds = collectPendingRunIds();
                if (pendingRunIds.length === 0) {
                    return { drained: true, pendingRunIds: [] };
                }
                const executions = [...activeExecutions.values()].flatMap((pending) => [...pending]);
                if (executions.length > 0) {
                    await Promise.race([Promise.allSettled(executions), sleep(pollIntervalMs)]);
                    continue;
                }
                await sleep(pollIntervalMs);
            }
            return {
                drained: false,
                pendingRunIds: collectPendingRunIds(),
            };
        },
        reset() {
            sessionManager.reset();
            activeRunIds.clear();
            activeExecutions.clear();
            settledRunIds.clear();
        },
    };
}
/** Create detached run shutdown lifecycle. */
export function createDetachedRunShutdownLifecycle(options) {
    const drainTimeoutMs = options.drainTimeoutMs ?? DEFAULT_DETACHED_RUN_DRAIN_TIMEOUT_MS;
    return {
        setShuttingDown() {
            const cancelledRunIds = options.tracker.cancelAllRuns();
            if (cancelledRunIds.length === 0) {
                return;
            }
            options.logger.info("Cancelled active detached durable runs during shutdown", {
                runIds: cancelledRunIds,
                count: cancelledRunIds.length,
            });
        },
        async stop() {
            const drainResult = await options.tracker.waitForDrain({
                timeoutMs: drainTimeoutMs,
                pollIntervalMs: options.pollIntervalMs,
            });
            if (!drainResult.drained) {
                options.logger.error(DETACHED_RUN_DRAIN_TIMEOUT_MESSAGE, {
                    pendingRunIds: drainResult.pendingRunIds,
                    count: drainResult.pendingRunIds.length,
                });
                throw AGENT_TIMEOUT.create({ detail: DETACHED_RUN_DRAIN_TIMEOUT_MESSAGE });
            }
            options.logger.info("All connections and detached durable runs drained, exiting");
        },
    };
}
